synchronized (s) {
    Map<String, String> map = tickets(s);
    while (map.size() >= 32) map.remove(map.keySet().iterator().next());
    String token = UUID.randomUUID().toString();
    map.put(token, purpose);
    return token;
}

synchronized (s) {
    String token = request.getParameter("operationToken");
    Map<String, String> map = tickets(s);
    if (token == null || !purpose.equals(map.get(token)))
        throw new BankException(409, "DUPLICATE", "이미 처리되었거나 만료된 요청입니다. 화면을 다시 열어주세요.");
    map.remove(token);
    return token;
}

synchronized (session) {
    TransferDraft draft = (TransferDraft) session.getAttribute("TRANSFER_DRAFT");
    if (draft == null || !draft.id.equals(request.getParameter("requestId")))
        throw new BankException(409, "DUPLICATE", "이미 처리되었거나 만료된 이체 요청입니다.");
    session.removeAttribute("TRANSFER_DRAFT");
    return draft;
}

synchronized (session) {
    String token = (String) session.getAttribute("CSRF");
    if (token == null) {
        byte[] bytes = new byte[24];
        new SecureRandom().nextBytes(bytes);
        token = Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
        session.setAttribute("CSRF", token);
    }
    return token;
}

